import {NAMES,COLORS,CASINOS,EFFECTS,SPECIALS,sum,createGame,nextRound,rollDice,placeDice,skipTurn,canSkip,outcome,previewTable,botChoice,botShouldSkip,winners,validSave} from './core.mjs';
const $=s=>document.querySelector(s),app=$('#app'),modal=$('#modal');
const SAVE='vegas-night-save-v3',PREF='vegas-night-prefs-v2';
const read=k=>{try{return JSON.parse(localStorage.getItem(k))}catch{return null}};
const write=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v));return true}catch{return false}};
const ART=['denim-final.png','cowboy-final.png','owner-final.png','bunny-final.png'];
const HEIGHT=[.87,.98,1,.94],LABEL=['短裤女士','筹码牛仔','赌场老板','兔女郎'];
const SYMBOL=['◆','●','■','▲'],MODE={half:'1–3 特殊赌场',all:'六座全部特殊',classic:'六座经典赌场'};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>`${n/10000}万`,awardFor=(o,i)=>sum(o.awards.filter(a=>a.player===i).map(a=>a.amount));
const dots={1:[4],2:[0,8],3:[0,4,8],4:[0,2,6,8],5:[0,2,4,6,8],6:[0,2,3,5,6,8]};
function die(n){return `<span class="die" aria-hidden="true">${Array.from({length:9},(_,i)=>`<i class="${dots[n].includes(i)?'':'off'}"></i>`).join('')}</span>`;}
let prefs={sound:true,fast:false,motion:true,...read(PREF)},saved=read(SAVE),game=validSave(saved)?saved:null;
let selected=0,busy=false,timer=0,generation=0,audio,dialogType='',preview=false,storageOK=true;
function sound(kind){if(!prefs.sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const fs=kind==='roll'?[160,250,190,310]:kind==='win'?[523,659,784]:kind==='skip'?[350,250]:kind==='tie'?[220,185]:[460,640];fs.forEach((f,i)=>{const o=audio.createOscillator(),v=audio.createGain(),t=audio.currentTime+i*.075;o.type=kind==='roll'?'triangle':'sine';o.frequency.setValueAtTime(f,t);v.gain.setValueAtTime(.001,t);v.gain.linearRampToValueAtTime(.05,t+.007);v.gain.exponentialRampToValueAtTime(.001,t+.13);o.connect(v);v.connect(audio.destination);o.start(t);o.stop(t+.15);});}catch{}}
function persist(){if(game&&!preview)storageOK=write(SAVE,game);}
function human(){return game.turn<game.humans;}
function canAct(){return game&&!preview&&!busy&&!modal.open&&human();}
function announce(s){$('#announce').textContent=s;}
function portrait(i,extra=''){return `<img class="character-art ${extra}" src="./assets/${ART[i]}" alt="${LABEL[i]}" style="--height:${HEIGHT[i]}" draggable="false">`;}
function seat(i){const p=game.players[i],active=i===game.turn&&!['settled','finished'].includes(game.phase);return `<section class="seat ${active?'active':''} seat-${i}" style="--pc:${COLORS[i]}"><div class="seat-top"><span>${SYMBOL[i]} ${i<game.humans?'玩家':'电脑'}</span><span>${active?'正在行动':p.left?'等待出手':'本轮完成'}</span></div><button class="portrait-button" data-character="${i}" aria-label="查看${LABEL[i]}立绘">${portrait(i)}</button><div class="seat-caption"><h2>${esc(p.name)}</h2><div class="seat-stats"><strong>${money(p.cash)}</strong><span>剩 <b>${p.left}</b> 颗骰子</span></div></div></section>`;}
function table(t,i,choosing,done){
  const n=game.roll.filter(x=>x===i+1).length,active=choosing&&n>0,staged=selected===i+1&&choosing,v=staged?previewTable(game,i+1):t,o=outcome(v),fx=EFFECTS[t.effect];
  let forecast=staged?`预览：${o.ties.includes(game.turn)?'撞数，暂时出局':awardFor(o,game.turn)?`可拿 ${money(awardFor(o,game.turn))}`:'暂时拿不到钱'}`:o.ties.length?`${o.ties.map(j=>SYMBOL[j]).join(' ')} 撞数出局`:o.awards.length?`${SYMBOL[o.awards[0].player]} ${done?'获得':'暂领'} ${money(awardFor(o,o.awards[0].player))}`:active?`可放 ${n} 颗 · 点击预览`:'等待入桌';
  return `<article class="casino casino-${i+1} ${active?'available':''} ${staged?'selected':''} ${t.effect!=='classic'?'special':''}"><button class="table-target" data-face="${i+1}" ${active?'':'disabled'} aria-label="${i+1}号${t.name}，总奖金${money(sum(t.notes))}，${active?`放入${n}颗`:'当前不可放置'}"><div class="casino-head"><span class="face">${die(i+1)}</span><div><h3>${t.name}</h3><div class="casino-total">总额 <strong>${money(sum(t.notes))}</strong></div></div></div><div class="banknotes" aria-label="${t.notes.map(money).join('、')}">${t.notes.map(v=>`<span>${money(v)}</span>`).join('')}</div><div class="counts">${v.counts.map((c,j)=>`<span style="--pc:${COLORS[j]}" class="pile ${c?'':'empty'} ${o.ties.includes(j)?'tied':''}" title="${esc(game.players[j].name)}：${c}颗"><small>${SYMBOL[j]}</small>${c||'–'}</span>`).join('')}</div><div class="forecast">${forecast}</div></button><button class="effect" data-info="${i+1}" aria-label="查看${i+1}号赌场规则：${fx.name}"><span>${t.effect!=='classic'?'✦':'◇'} ${fx.name}</span><span>ⓘ</span></button></article>`;
}
function render(){
  document.documentElement.classList.toggle('no-motion',!prefs.motion);
  const g=game,done=['settled','finished'].includes(g.phase),choosing=g.phase==='choose'&&human()&&!busy&&!preview,total=sum(g.tables.flatMap(t=>t.notes));
  const current=selected?g.tables[selected-1]:null;
  app.innerHTML=`<main class="shell"><header class="top"><div class="brand"><span class="brand-mark">V</span><div><div class="eyebrow">VEGAS AFTER DARK</div><h1>拉斯维加斯 <span>· 骰子之夜</span></h1></div></div><nav class="tools" aria-label="游戏菜单"><button class="quiet" data-action="rules">玩法</button><button class="quiet" data-action="settings">${prefs.sound?'声音 · 开':'声音 · 关'}</button><button class="quiet" data-action="pause">暂停</button></nav></header>
  <div class="roundbar"><div class="rounds"><span>第 <strong>${g.round}</strong> / 4 轮</span>${[1,2,3,4].map(n=>`<i class="${n<=g.round?'on':''}"></i>`).join('')}</div><span class="mode-tag">${MODE[g.rules]}</span><span class="sort-hint">每桌2张 · 1 → 6 总额递增</span></div>
  <div class="game-scene"><aside class="cast-rail left-rail" aria-label="左侧玩家">${seat(0)}${seat(2)}</aside><section class="arena" aria-label="顺时针排列的六座赌场"><div class="orbit" aria-hidden="true"></div>${g.tables.map((t,i)=>table(t,i,choosing,done)).join('')}<div class="table-center"><div class="center-star">✧</div><span class="eyebrow">${current?'CASINO '+current.face:'TONIGHT’S POT'}</span><div class="pot">${current?current.name:money(total)}</div><p>${current?EFFECTS[current.effect].short:'六座赌场 · 各凭本事'}</p><div class="center-turn" style="--pc:${COLORS[g.turn]}">${done?'本轮下注结束':`${SYMBOL[g.turn]} ${esc(g.players[g.turn].name)}`}</div><small>${done?'查看下方结算':busy?'骰子正在落定':g.phase==='choose'?'选点下注，或跳过等下次':'准备掷骰'}</small></div></section><aside class="cast-rail right-rail" aria-label="右侧玩家">${seat(1)}${seat(3)}</aside></div>
  <section class="control" aria-label="当前回合"><div class="roll-area"><div class="turntitle">${done?'本轮筹码已落定':busy?'骰子正在落定…':human()?`轮到<span style="color:${COLORS[g.turn]}">${esc(g.players[g.turn].name)}</span>`:`${esc(g.players[g.turn].name)}正在考虑…`}</div><div class="turnhint">${done?'逐桌查看特殊效果和奖金归属。':g.phase==='choose'?selected?`选择 ${selected} 点的 ${g.roll.filter(x=>x===selected).length} 颗，一起放进${CASINOS[selected-1]}。`:'不满意可以跳过：不下注、留骰，等下次轮到自己再掷。':`掷出剩余 ${g.players[g.turn].left} 颗骰子，选择一种点数下注。`}</div><div class="dice-row ${busy?'rolling':''}" aria-label="本次骰子">${g.roll.length?[...g.roll].sort((a,b)=>a-b).map(n=>`<button class="dicebutton ${selected===n?'picked':''}" data-face="${n}" ${choosing?'':'disabled'} aria-label="选择${n}点">${die(n)}</button>`).join(''):Array.from({length:Math.min(g.players[g.turn].left,8)},()=>'<span class="emptydie" aria-hidden="true">·</span>').join('')}</div></div><div class="actionarea"><button class="primary" data-action="${done?'summary':g.phase==='choose'?'confirm':'roll'}" ${done?'':!human()||busy||preview||(g.phase==='choose'&&!selected)?'disabled':''}>${done?'查看结算':busy?'掷骰中…':!human()?'等待对手':g.phase==='choose'?selected?`放入 ${g.roll.filter(x=>x===selected).length} 颗 →`:'先选一种点数':'掷骰子'}</button>${!done?`<button class="skip" data-action="skip" ${choosing?'':'disabled'}>跳过本次 · 下次重投</button>`:''}<div class="keyhint">空格掷骰 · 1–6 选点 · Enter 确认 · S 跳过</div></div></section>
  <div class="table-log" aria-label="牌桌动态"><span>牌桌动态</span><p>${esc(g.history[0]||'等待开局')}</p><button data-action="history" class="text-button">查看记录</button></div><footer><span>${g.humans===1?'你与三位电脑':g.humans===4?'四人同屏轮流':'两人同屏 + 两位电脑'} · ${storageOK?'本机自动保存':'本机无法保存进度'}</span><span>自定义规则版 · 无真实金钱交易</span></footer></main>`;
}
function stopTimer(){clearTimeout(timer);generation++;}
function scheduleBot(){clearTimeout(timer);if(!game||preview||human()||modal.open||document.hidden||busy||!['ready','choose'].includes(game.phase))return;timer=setTimeout(()=>{if(modal.open||document.hidden)return;if(game.phase==='ready')doRoll();else if(botShouldSkip(game))doSkip();else{selected=botChoice(game);render();timer=setTimeout(()=>{if(!modal.open&&!document.hidden)commit();},prefs.fast?100:700);}},prefs.fast?120:650);}
function doRoll(){if(busy||modal.open||game.phase!=='ready')return;stopTimer();const gen=generation;rollDice(game);selected=0;busy=true;sound('roll');render();persist();timer=setTimeout(()=>{if(gen!==generation)return;busy=false;render();announce(`${game.players[game.turn].name}掷出${game.roll.join('、')}`);scheduleBot();},prefs.motion?(prefs.fast?150:500):20);}
function commit(){if(!selected||game.phase!=='choose'||busy||modal.open)return;const actor=game.turn,face=selected;if(!placeDice(game,face))return;selected=0;persist();sound(outcome(game.tables[face-1]).ties.includes(actor)?'tie':'place');render();announce(game.history[0]);if(['settled','finished'].includes(game.phase))timer=setTimeout(showSummary,prefs.fast?100:650);else scheduleBot();}
function doSkip(){if(busy||modal.open||!canSkip(game))return;stopTimer();skipTurn(game);selected=0;persist();sound('skip');render();announce(game.history[0]);scheduleBot();}
function openDialog(type,html){stopTimer();busy=false;dialogType=type;modal.className=type;modal.innerHTML=html;if(!modal.open)modal.showModal();render();}
function closeDialog(){modal.close();dialogType='';scheduleBot();}
function welcome(){if(!game){game=createGame();preview=true;}render();openDialog('welcome',`<div class="welcome-heading"><div class="eyebrow">VEGAS AFTER DARK</div><h2>今晚，谁把奖金带走？</h2><p>六座赌场，一桌熟面孔。</p></div><div class="cast-lineup">${[0,1,2,3].map(i=>`<div class="cast-member" style="--pc:${COLORS[i]};--height:${HEIGHT[i]}">${portrait(i)}<span>${LABEL[i]}</span></div>`).join('')}</div><div class="setup"><label>今晚和谁玩？<select id="mode"><option value="1">独自练手 · 你 + 3 位电脑</option><option value="2">两人同屏 + 2 位电脑</option><option value="4">四位朋友 · 同屏轮流</option></select></label><label>赌场规则<select id="ruleset"><option value="half">1–3 随机特殊 · 4–6 经典</option><option value="all">六座全部随机特殊</option><option value="classic">六座全部经典</option></select></label></div><div class="welcome-actions"><button class="primary" data-action="start">入座，开一局</button>${!preview?'<button class="quiet" data-action="resume">继续上次牌局</button>':''}</div><p class="welcome-note">不满意可跳过本次，不下注、不扣骰，下次轮到自己重投。<br>4 轮定胜负 · 暂不支持远程联机</p>`);}
function showRules(){openDialog('rules',`<div class="eyebrow">TABLE RULES</div><h2>怎么玩</h2><div class="steps"><p><b>掷骰与下注</b>每人每轮8颗，掷出所有剩余骰子，选一种点数，把该点数全部骰子放进对应赌场。</p><p><b>跳过与重投</b>掷完不满意，直接跳过本次，不选骰、不下注。骰子全部保留，免费且不限次数。下一位先行动，再轮到你时重投。若只剩你有骰子，会立即再次轮到你。</p><p><b>奖金与胜负</b>每大轮每座赌场固定发两张钞票，按两张合计从小到大分配到1–6号；同总额允许并列。所有人放完才结算，四轮奖金最多者获胜；同额比钞票张数，再同则共享胜利。</p></div><p><b>特殊效果</b>每大轮从六种效果中随机抽取、不重复分配。默认只给1–3号，4–6号保持经典；全特殊模式给六座都抽取。本轮下注期间效果不变。</p><h3>当前：${MODE[game.rules]}</h3><div class="rule-list">${game.tables.map(t=>`<div><b>${t.face} · ${t.name} — ${EFFECTS[t.effect].name}</b><p>${EFFECTS[t.effect].text}</p></div>`).join('')}</div><p class="fineprint">特殊赌场为本版自定义设计，不是官方扩展复刻。基础桌游机制：Rüdiger Dorn。<a href="https://www.ravensburger.org/spielanleitungen/ecm/Spielanleitungen/26938_Vegas_EN.pdf" target="_blank" rel="noreferrer">经典规则 ↗</a></p><button class="primary" data-action="close">明白了，回到牌桌</button>`);}
function showInfo(face){const t=game.tables[face-1],fx=EFFECTS[t.effect];openDialog('info',`<div class="eyebrow">CASINO ${face}</div><h2>${t.name} · ${fx.name}</h2><p>${fx.text}</p><div class="info-money">本桌总奖金 <strong>${money(sum(t.notes))}</strong><span>${t.notes.map(money).join(' + ')}</span></div><p class="fineprint">排序与撞数均按本桌规则处理；预览只是当前局面，别人之后仍可改变它。</p><button class="primary" data-action="close">回到牌桌</button>`);}
function showSettings(){openDialog('settings',`<div class="eyebrow">SETTINGS</div><h2>按你的节奏来</h2><label class="settingsrow">骰子与结算音效<input type="checkbox" data-pref="sound" ${prefs.sound?'checked':''}></label><label class="settingsrow">加快电脑出手<input type="checkbox" data-pref="fast" ${prefs.fast?'checked':''}></label><label class="settingsrow">掷骰动画<input type="checkbox" data-pref="motion" ${prefs.motion?'checked':''}></label><button class="primary" data-action="close">回到牌桌</button>`);}
function showPause(){openDialog('pause',`<div class="eyebrow">TAKE YOUR TIME</div><h2>牌桌暂停了</h2><p>${storageOK?'当前进度已保存在这台设备。':'当前浏览器无法保存进度，请保持页面打开。'}</p><button class="primary" data-action="close">继续牌局</button><button class="quiet" data-action="restart-prompt">重新开一桌</button>`);}
function showSummary(){if(!['settled','finished'].includes(game.phase))return;const gains=[0,0,0,0];game.settlements.forEach(o=>o.awards.forEach(a=>gains[a.player]+=a.amount));const final=game.phase==='finished',win=final?winners(game):[];sound('win');openDialog('summary',`<div class="eyebrow">${final?'THE FINAL COUNT':`ROUND ${game.round} · PAYOUT`}</div><h2>${final?`${win.map(i=>esc(game.players[i].name)).join('、')}${win.length>1?'并列获胜':'赢下牌局'}`:`第 ${game.round} 轮结算`}</h2><p>${final?'四轮结束。奖金相同按钞票张数排名。':'每桌按照自己的特殊规则分配奖金。'}</p><div class="resultrows">${game.players.map((p,i)=>({p,i})).sort((a,b)=>final?b.p.cash-a.p.cash||b.p.notes-a.p.notes:gains[b.i]-gains[a.i]).map(({p,i})=>`<div class="resultrow"><span style="color:${COLORS[i]}">${win.includes(i)?'✦ ':''}${esc(p.name)}${final?` <small>· ${p.notes}张钞票</small>`:''}</span><strong>${final?money(p.cash):'+'+money(gains[i])}</strong></div>`).join('')}</div><div class="summarytable">${game.tables.map((t,i)=>{const o=game.settlements[i],recipients=[...new Set(o.awards.map(a=>a.player))];return `<div class="summaryline"><b>${i+1} · ${t.name}</b><span>${EFFECTS[t.effect].name}</span><p>${recipients.length?recipients.map(j=>`${esc(game.players[j].name)} +${money(awardFor(o,j))}`).join(' / '):'无人获得奖金'}</p>${o.ties.length?`<small>撞数出局：${o.ties.map(j=>esc(game.players[j].name)).join('、')}</small>`:''}</div>`}).join('')}</div><button class="primary" data-action="${final?'again':'next'}">${final?'再来一局':`进入第 ${game.round+1} 轮`}</button><button class="quiet" data-action="close">查看牌桌</button>`);}
app.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.face){if(canAct()&&game.phase==='choose'){selected=Number(b.dataset.face);render();}return;}if(b.dataset.info){showInfo(Number(b.dataset.info));return;}if(b.dataset.character!==undefined){const i=Number(b.dataset.character);openDialog('character',`<h2>${LABEL[i]}</h2>${portrait(i)}<button class="primary" data-action="close">回到牌桌</button>`);return;}const a=b.dataset.action;if(a==='rules')showRules();if(a==='settings')showSettings();if(a==='pause')showPause();if(a==='summary')showSummary();if(a==='roll'&&canAct())doRoll();if(a==='confirm'&&canAct())commit();if(a==='skip'&&canAct())doSkip();if(a==='history')openDialog('history',`<h2>牌桌记录</h2><div class="history-list">${game.history.map(s=>`<p>${esc(s)}</p>`).join('')}</div><button class="primary" data-action="close">回到牌桌</button>`);});
modal.addEventListener('click',e=>{const a=e.target.closest('button')?.dataset.action;if(!a)return;if(a==='start'){const humans=Number($('#mode').value),rules=$('#ruleset').value;preview=false;game=createGame(humans,Math.random,{rules});selected=0;closeDialog();persist();render();showRules();}if(a==='resume'){preview=false;closeDialog();render();}if(a==='close'){if(preview){welcome();return;}closeDialog();render();}if(a==='next'){nextRound(game);selected=0;closeDialog();persist();render();scheduleBot();}if(a==='again'){closeDialog();welcome();}if(a==='restart-prompt')openDialog('restart',`<h2>重新开一桌？</h2><p>开始新牌局会替换当前进度。</p><button class="primary" data-action="again">选择新牌局</button><button class="quiet" data-action="close">继续当前牌局</button>`);});
modal.addEventListener('change',e=>{const k=e.target.dataset.pref;if(k){prefs[k]=e.target.checked;write(PREF,prefs);render();}});
modal.addEventListener('cancel',e=>{e.preventDefault();if(dialogType==='welcome')return;closeDialog();render();});
document.addEventListener('keydown',e=>{if(modal.open||e.repeat)return;if(e.key==='Escape'){showPause();return;}if(!canAct())return;if(e.code==='Space'&&game.phase==='ready'){e.preventDefault();doRoll();}if(/^[1-6]$/.test(e.key)&&game.phase==='choose'&&game.roll.includes(Number(e.key))){selected=Number(e.key);render();}if(e.key==='Enter'&&game.phase==='choose'&&selected){e.preventDefault();commit();}if(e.key.toLowerCase()==='s'&&game.phase==='choose'){e.preventDefault();doSkip();}});
document.addEventListener('visibilitychange',()=>{if(document.hidden){stopTimer();busy=false;persist();if(!modal.open&&!preview)showPause();}});window.addEventListener('pagehide',persist);welcome();
if(document.modelContext?.registerTool){const life=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'read_vegas_table',description:'Read visible game state, casino effects, dice and payouts without exposing undealt notes.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(input&&Object.keys(input).length)throw Error('No arguments accepted');return {round:game.round,phase:game.phase,turn:game.turn,players:game.players,roll:game.roll,tables:game.tables,paused:modal.open};}},{signal:life.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>life.abort(),{once:true});}
